import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-BsOuDHI-.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/tutorial/job-execution-middleware.html","title":"Job Execution Middleware","lang":"en-US","frontmatter":{"title":"Job Execution Middleware"},"git":{"updatedTime":1788441191000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5.1","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"8dee9f767ead84b6e47c023533864d1d3e3178ae","time":1788441191000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"The release post carries the day 4.0.0 shipped","coAuthors":[{"name":"Claude Fable 5.1","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/tutorial/job-execution-middleware.md"}`),u={name:`job-execution-middleware.md`};function d(s,l,u,d,f,p){let m=a(`RouteLink`);return n(),o(`div`,null,[l[12]||=t(`<h1 id="job-execution-middleware" tabindex="-1"><a class="header-anchor" href="#job-execution-middleware"><span>Job Execution Middleware</span></a></h1><p>Middleware wraps every job a scheduler executes. It is where a cross-cutting concern lives — a log scope, a tenant context, a metric, a translation of what a third-party library throws — when that concern has to <em>surround</em> the call to the job rather than merely hear about it.</p><p>Listeners cannot do this. An <code>IJobListener</code> is notified before the job runs and again after it has run, but the execution happens <em>between</em> the two notifications rather than <em>inside</em> them, so a listener cannot open an <code>await using</code> around it, cannot decline to run it, and cannot catch what it threw. Before 4.0 the only place left for such code was a job that wrapped another job, which is why several frameworks built on Quartz ship exactly that adapter.</p><h2 id="the-interface" tabindex="-1"><a class="header-anchor" href="#the-interface"><span>The interface</span></a></h2><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">delegate</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">JobExecutionDelegate</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">interface</span> <span class="token class-name">IJobExecutionMiddleware</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token return-type class-name">ValueTask</span> <span class="token function">Invoke</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">JobExecutionDelegate</span> next<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>next</code> is the rest of the chain, ending in the job. Await it to run the job; do not, and the job does not run. Awaiting it twice is legal and runs the job twice inside the one firing — see <a href="#translating-exceptions">Translating exceptions</a> for why that is not how you retry.</p><h2 id="writing-one" tabindex="-1"><a class="header-anchor" href="#writing-one"><span>Writing one</span></a></h2><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">LogScopeMiddleware</span><span class="token punctuation">(</span><span class="token class-name">ILogger<span class="token punctuation">&lt;</span>LogScopeMiddleware<span class="token punctuation">&gt;</span></span> logger<span class="token punctuation">)</span> <span class="token punctuation">:</span> IJobExecutionMiddleware</span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Invoke</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">JobExecutionDelegate</span> next<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">using</span> <span class="token class-name">IDisposable<span class="token punctuation">?</span></span> scope <span class="token operator">=</span> logger<span class="token punctuation">.</span><span class="token function">BeginScope</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">Dictionary<span class="token punctuation">&lt;</span><span class="token keyword">string</span><span class="token punctuation">,</span> <span class="token keyword">object</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token punctuation">[</span><span class="token string">&quot;JobKey&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">[</span><span class="token string">&quot;FireInstanceId&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> context<span class="token punctuation">.</span>FireInstanceId<span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">await</span> <span class="token function">next</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="registering" tabindex="-1"><a class="header-anchor" href="#registering"><span>Registering</span></a></h2><p>Middleware belongs to a scheduler, so it is registered where the scheduler is configured. The same three shapes listeners have: the container builds it, you build it from the container, or you hand over one you already have.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// built by the container, so it can take dependencies of its own</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobMiddleware</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>LogScopeMiddleware<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// built by you, from this scheduler&#39;s services</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">AddJobMiddleware</span><span class="token punctuation">(</span>provider <span class="token operator">=&gt;</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">MeteredMiddleware</span><span class="token punctuation">(</span>provider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>IMeterFactory<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// one you already have</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">AddJobMiddleware</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TenantScopeMiddleware</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The standalone builder takes the same calls, because it <em>is</em> an <code>IQuartzBuilder</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">IScheduler</span> scheduler <span class="token operator">=</span> <span class="token keyword">await</span> QuartzSchedulerBuilder</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span> q</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">UseInMemoryStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJobMiddleware</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>LogScopeMiddleware<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">BuildScheduler</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Registering a middleware for <code>AddQuartz(&quot;reporting&quot;, …)</code> puts it in that scheduler&#39;s pipeline alone. A named scheduler&#39;s middleware is its own, the way its listeners and its job store are.</p></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>A middleware is built <strong>once, from the container&#39;s root</strong>, when the scheduler&#39;s resources are. Its constructor dependencies must therefore be singletons: a scoped one throws <code>Cannot resolve scoped service … from root provider</code> where scope validation is on — the Host&#39;s default in Development — and becomes a captive dependency living as long as the scheduler where it is not. The name is ASP.NET Core&#39;s, but the lifetime is a listener&#39;s.</p><p>Take an <code>IServiceScopeFactory</code> and open a scope inside <code>Invoke</code> instead:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">AuditMiddleware</span><span class="token punctuation">(</span><span class="token class-name">IServiceScopeFactory</span> scopeFactory<span class="token punctuation">)</span> <span class="token punctuation">:</span> IJobExecutionMiddleware</span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Invoke</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">JobExecutionDelegate</span> next<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// A middleware is built once, from the container&#39;s root, so a scoped service cannot be a</span></span>
<span class="line">        <span class="token comment">// constructor parameter. Resolve it per firing instead.</span></span>
<span class="line">        <span class="token keyword">await</span> <span class="token keyword">using</span> <span class="token class-name">AsyncServiceScope</span> scope <span class="token operator">=</span> scopeFactory<span class="token punctuation">.</span><span class="token function">CreateAsyncScope</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token class-name">AuditLog</span> audit <span class="token operator">=</span> scope<span class="token punctuation">.</span>ServiceProvider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>AuditLog<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">await</span> audit<span class="token punctuation">.</span><span class="token function">Starting</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">await</span> <span class="token function">next</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The firing&#39;s own scope — the one the job was resolved from — is reachable through <code>IJobExecutionContextAccessor</code>; see <a href="#per-firing-state">Per-firing state</a>.</p></div><h2 id="order" tabindex="-1"><a class="header-anchor" href="#order"><span>Order</span></a></h2><p>Middleware runs in registration order, <strong>outermost first</strong>. The first registered sees the firing before the second does and sees its result after it, which is the ordering a log scope or a transaction has to be planned around:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">q.AddJobMiddleware&lt;A&gt;();     A ─┐</span>
<span class="line">q.AddJobMiddleware&lt;B&gt;();        B ─┐</span>
<span class="line">                                   job</span>
<span class="line">                                B ─┘</span>
<span class="line">                             A ─┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Each call adds a stage, so registering the same type twice puts it in the chain twice.</p><p>The chain is composed <strong>once</strong>, when the scheduler is built, and one instance of each middleware serves every firing that scheduler performs. A middleware must therefore keep no per-firing state in a field — see <a href="#per-firing-state">Per-firing state</a> below.</p><p>A middleware registered through <code>ConfigureAllQuartzSchedulers</code> always composes <strong>inside</strong> one registered in a scheduler&#39;s own <code>AddQuartz</code> callback, whichever of the two calls was written first: a scheduler&#39;s own configuration runs before what every scheduler was told. That is deliberate, and it is what a library embedding Quartz relies on — what the library wraps, such as an outbox or a unit of work, belongs inside what the application wraps, such as its tenant scope. Because the ordering does not depend on the order of the calls, a library cannot change it by being registered earlier.</p><h2 id="where-it-runs" tabindex="-1"><a class="header-anchor" href="#where-it-runs"><span>Where it runs</span></a></h2><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>after the trigger and job listeners have been notified</td><td>a fire a listener vetoed never reaches the pipeline</td></tr><tr><td>inside the execution span and the duration measurement</td><td>what a middleware costs is part of what the firing cost, and anything it traces is a child of <code>Quartz.Job.Execute</code></td></tr><tr><td>outside the run shell&#39;s exception handling</td><td>what a middleware throws is classified exactly as though the job had thrown it</td></tr><tr><td>inside the store&#39;s concurrency handling</td><td><code>[DisallowConcurrentExecution]</code> is enforced above the pipeline, so a middleware never sees two firings of one job overlapping</td></tr></tbody></table><h2 id="short-circuiting" tabindex="-1"><a class="header-anchor" href="#short-circuiting"><span>Short-circuiting</span></a></h2><p>A middleware that does not call <code>next</code> keeps the call to itself. The job does not run; everything else about the firing is unchanged — the listeners are notified as usual, and the trigger is left where a successful execution leaves it.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">FeatureFlagMiddleware</span><span class="token punctuation">(</span><span class="token class-name">FeatureFlags</span> flags<span class="token punctuation">)</span> <span class="token punctuation">:</span> IJobExecutionMiddleware</span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Invoke</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">JobExecutionDelegate</span> next<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// Not calling next means the job does not run. The firing still completes, the listeners are</span></span>
<span class="line">        <span class="token comment">// still notified, and the trigger is left where a successful execution leaves it.</span></span>
<span class="line">        <span class="token keyword">return</span> flags<span class="token punctuation">.</span><span class="token function">IsEnabled</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">)</span> <span class="token punctuation">?</span> <span class="token function">next</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span> <span class="token punctuation">:</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>This is not a veto. A trigger listener&#39;s <code>VetoJobExecution</code> is the <em>scheduler&#39;s</em> refusal: it raises <code>JobExecutionVetoed</code>, and the firing ends there. A middleware that declines is invisible from outside.</p><h2 id="translating-exceptions" tabindex="-1"><a class="header-anchor" href="#translating-exceptions"><span>Translating exceptions</span></a></h2><p>A middleware runs outside the run shell&#39;s exception classification, so a <code>JobExecutionException</code> it throws is honoured exactly like one the job raised — including <code>RefireImmediately</code> and the unschedule flags — and a plain exception is wrapped the same way. That makes middleware the place to teach Quartz what a library&#39;s own failures mean:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TransientFailureMiddleware</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJobExecutionMiddleware</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Invoke</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">JobExecutionDelegate</span> next<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">try</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">await</span> <span class="token function">next</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">HttpRequestException</span> e<span class="token punctuation">)</span> <span class="token keyword">when</span> <span class="token punctuation">(</span>e<span class="token punctuation">.</span>StatusCode <span class="token operator">==</span> System<span class="token punctuation">.</span>Net<span class="token punctuation">.</span>HttpStatusCode<span class="token punctuation">.</span>TooManyRequests<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// Quartz understands this; it does not understand HttpRequestException.</span></span>
<span class="line">            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobExecutionException</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> RefireImmediately <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Catching a failure and awaiting a delay before calling <code>next</code> again is not a retry. It holds a thread-pool slot for the whole wait, and the attempt is lost if the process stops. A trigger&#39;s retry policy is the tool for that.</p></div><h2 id="per-firing-state" tabindex="-1"><a class="header-anchor" href="#per-firing-state"><span>Per-firing state</span></a></h2><p>One middleware instance serves every firing, so a field is the wrong place to keep anything about the firing in hand. Two things that are the right place:</p><p><strong>An <code>AsyncLocal&lt;T&gt;</code>.</strong> The value travels with the execution context, so the job and everything it calls read the one their own firing set:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TenantScopeMiddleware</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJobExecutionMiddleware</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Invoke</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">JobExecutionDelegate</span> next<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// An AsyncLocal, not a field: one instance of this middleware serves every firing the scheduler</span></span>
<span class="line">        <span class="token comment">// performs, and several of them can be in flight at once.</span></span>
<span class="line">        TenantScope<span class="token punctuation">.</span>Current<span class="token punctuation">.</span>Value <span class="token operator">=</span> context<span class="token punctuation">.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">try</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">await</span> <span class="token function">next</span><span class="token punctuation">(</span>context<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">finally</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            TenantScope<span class="token punctuation">.</span>Current<span class="token punctuation">.</span>Value <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>The job&#39;s dependency-injection scope.</strong> <code>ConfigureJobScope</code> runs once per firing, before anything in the scope is resolved, and is handed the <code>TriggerFiredBundle</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Populated once per firing, before anything in the job&#39;s scope is resolved.</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">ConfigureJobScope</span><span class="token punctuation">(</span><span class="token punctuation">(</span>scope<span class="token punctuation">,</span> bundle<span class="token punctuation">,</span> scheduler<span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span>
<span class="line">        scope<span class="token punctuation">.</span>ServiceProvider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>TenantHolder<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Tenant <span class="token operator">=</span> bundle<span class="token punctuation">.</span>Trigger<span class="token punctuation">.</span>Key<span class="token punctuation">.</span>Group<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>No <code>IServiceScope</code> is threaded through <code>Invoke</code>, deliberately: the scope belongs to the firing rather than to any one middleware, and code that needs the firing itself can read it from <code>IJobExecutionContextAccessor.Current</code>, which is set for the whole execution — including inside the pipeline, on the way in and on the way out.</p><p><strong><code>context.MergedJobDataMap</code>,</strong> to hand something to a <em>listener</em>. An <code>AsyncLocal</code> does not reach one: an async method restores its caller&#39;s execution context, so what a middleware sets inside <code>Invoke</code> is gone by the time the run shell notifies listeners. The merged map is not — it is this firing&#39;s own copy of the job&#39;s and the trigger&#39;s data, built once and shared by everything that holds the context, so a value put into it is visible to the job, to the rest of the pipeline and to the listeners for as long as the firing lasts. Writing to it is safe and persists nothing: neither the job&#39;s nor the trigger&#39;s stored map is touched. Data that has to outlive the firing goes into <code>context.JobDetail.JobDataMap</code> on a job marked <code>[PersistJobDataAfterExecution]</code>, which is what a job store writes back.</p><h2 id="the-cancellation-token" tabindex="-1"><a class="header-anchor" href="#the-cancellation-token"><span>The cancellation token</span></a></h2><p>Forward the token you were given. Passing a different one to <code>next</code> changes what the job&#39;s <code>Execute</code> parameter is without changing <code>IJobExecutionContext.CancellationToken</code>, so the two stop being the same token and a job that reads the context sees the wrong one. That is the trap in writing a timeout as a middleware — and it is why the built-in one interrupts the firing instead.</p><h2 id="timing-a-job-out" tabindex="-1"><a class="header-anchor" href="#timing-a-job-out"><span>Timing a job out</span></a></h2><p><code>AddJobTimeout</code> registers the middleware Quartz ships for exactly this. It replaces <code>JobInterruptMonitorPlugin</code>, which is gone in 4.0 along with its <code>&quot;AutoInterruptable&quot;</code> and <code>&quot;MaxRunTime&quot;</code> job-data-map keys.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">builder<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// every job gets five minutes, unless it says otherwise</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">AddJobTimeout</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromMinutes</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// or: no scheduler-wide budget, and only the jobs carrying [JobTimeout] are bounded</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">AddJobTimeout</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A job varies the budget by declaring one, the way it declares <code>[DisallowConcurrentExecution]</code>. The attribute is inherited from a base class or from an interface the job implements, so a contract can set the budget for everything that fulfils it:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// Thirty seconds for this job, whatever the scheduler&#39;s default is.</span></span>
<span class="line"><span class="token punctuation">[</span><span class="token function">JobTimeout</span><span class="token punctuation">(</span><span class="token string">&quot;00:00:30&quot;</span><span class="token punctuation">)</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">ReportJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// Forward the token: a job that never looks at it cannot be stopped by anything, and is simply</span></span>
<span class="line">        <span class="token comment">// reported as having timed out once it finally returns.</span></span>
<span class="line">        <span class="token keyword">await</span> Task<span class="token punctuation">.</span><span class="token function">Delay</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromSeconds</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// No timeout at all, whatever the scheduler&#39;s default is.</span></span>
<span class="line"><span class="token punctuation">[</span><span class="token attribute"><span class="token class-name">JobTimeout</span><span class="token attribute-arguments"><span class="token punctuation">(</span><span class="token string">&quot;00:00:00&quot;</span><span class="token punctuation">)</span></span></span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">NightlyRebuildJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Precedence.</strong> The job type&#39;s <code>[JobTimeout]</code> decides whenever there is one — including when it says zero, which means the job has no timeout and is exempt from the scheduler-wide default rather than overruled by it. Without the attribute, <code>AddJobTimeout</code>&#39;s argument decides; without an argument, and on a scheduler that never called <code>AddJobTimeout</code> at all, nothing is bounded.</p><p><strong>What a timeout does.</strong> When the budget is spent, the firing is interrupted through <code>IScheduler.InterruptFireInstance</code> — the same path an operator&#39;s interrupt takes, so <code>IJobExecutionContext.CancellationToken</code> (the very token the job holds) is cancelled and <code>ISchedulerListener.JobInterrupted</code> is raised. Only the firing that overran is interrupted, because it is named by its fire instance id: two concurrent executions of one job are timed separately. The middleware then raises a <code>JobExecutionException</code> naming the budget. That second step is the point: an interrupt on its own is <em>success-shaped</em>, because the run shell treats a cancellation of the context&#39;s token as a completed firing, so without it a timeout would reach no listener, produce no error, and never be retried.</p>`,48),e(`p`,null,[l[1]||=e(`strong`,null,`A timeout is a retryable failure.`,-1),l[2]||=r(` Because it arrives as a `,-1),l[3]||=e(`code`,null,`JobExecutionException`,-1),l[4]||=r(`, the trigger's `,-1),c(m,{to:`/documentation/quartz-4.x/how-tos/retrying-failed-jobs.html`},{default:i(()=>[...l[0]||=[e(`code`,null,`RetryPolicy`,-1)]]),_:1}),l[5]||=r(` decides what happens next, exactly as it would for any other failure. A retry is an ordinary re-acquisition with a new fire instance, so the pipeline runs again and each attempt is handed the whole budget afresh.`,-1)]),l[13]||=t(`<div class="hint-container warning"><p class="hint-container-title">Warning</p><p><strong>A job that ignores its <code>CancellationToken</code> cannot be stopped.</strong> Cancellation is cooperative and nothing in .NET aborts running code. Such a job runs to completion, holding its thread-pool slot, and is reported as timed out only when it finally returns — which is worth knowing before a budget is relied on to free capacity. <code>CA2016</code> is the analyzer that flags a job failing to forward the token it was handed; turn it on.</p><p>An exception the job threw that is <em>not</em> a cancellation is left alone even when the budget had expired: it says more about what went wrong than the timeout does. The overrun is logged either way.</p></div><h2 id="middleware-or-a-listener" tabindex="-1"><a class="header-anchor" href="#middleware-or-a-listener"><span>Middleware or a listener?</span></a></h2><table><thead><tr><th>Use middleware when you need to</th><th>Use a listener when you need to</th></tr></thead><tbody><tr><td>wrap the execution — a scope, a stopwatch, a transaction</td><td>be told that something happened</td></tr><tr><td>decide whether the job runs at all</td><td>veto a fire (<code>ITriggerListener.VetoJobExecution</code>)</td></tr><tr><td>catch or translate what the job threw</td><td>react to the failure the run shell reports</td></tr><tr><td>set ambient state the job will read</td><td>react to scheduling events that are not executions at all — a trigger paused, the scheduler shutting down</td></tr><tr><td>act only on this scheduler&#39;s job executions</td><td>select which jobs or triggers you hear about, with a matcher</td></tr></tbody></table><p>Listeners stay notification-only, and none of this changes them. The two compose: a middleware can do its work and a listener can still record what happened.</p><h2 id="see-also" tabindex="-1"><a class="header-anchor" href="#see-also"><span>See also</span></a></h2>`,5),e(`ul`,null,[e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/tutorial/trigger-and-job-listeners.html`},{default:i(()=>[...l[6]||=[r(`Trigger and Job Listeners`,-1)]]),_:1})]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/tutorial/more-about-jobs.html`},{default:i(()=>[...l[7]||=[r(`More About Jobs`,-1)]]),_:1}),l[8]||=r(` — job scopes and `,-1),l[9]||=e(`code`,null,`ConfigureJobScope`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/how-tos/retrying-failed-jobs.html`},{default:i(()=>[...l[10]||=[r(`Retrying failed jobs`,-1)]]),_:1}),l[11]||=r(` — what a trigger does with the failure a timeout raises`,-1)])])])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};